    // Create a circulator starting at the given node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    // If the start node already satisfies the predicate, return it immediately.
    if (predicate.test(circ.getNode())) {
        return circ;
    }
    // Traverse until we hit the stop node or find a node that satisfies the predicate
