        // If the current node satisfies the predicate, return the circulator
        if (predicate.test(circ.getNode())) {
            return circ;
        }
        // If we reach the stop node, return the circulator pointing at it
        if (circ.getNode().equals(stop)) {
            return circ;
        }
    }
    // Fallback: return the circulator at the stop node if we never found a match.
    return circ;
}

