private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A null graph or vertex set cannot form a clique
    if (graph == null || vertices == null) {
        return false;
    }

    // A clique is trivially true for 0 or 1 vertex
    if (vertices.size() < 2) {
        return true;
    }

    // Check every unordered pair of vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2) {
                continue;            // ignore self‑loops
            }
            // For undirected graphs the edge can be queried in either direction
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

