public static String encodeTemplateNames(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder encoded = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            encoded.append("%7B");
        } else if (c == '}') {
            encoded.append("%7D");
        } else {
            encoded.append(c);
        }
    }
    return encoded.toString();
}

