public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    // Regular expression to find ${var} patterns
    Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
    Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();

    // Replace each occurrence with the corresponding property value.
    // Perform replacement iteratively until no more ${...} patterns remain.
    boolean found = false;
    while (matcher.find()) {
        found = true;
        String varName = matcher.group(1);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = ""; // Default to empty string if not found
        }
        // Escape backslashes and dollar signs in the replacement string for appendReplacement
        replacement = Matcher.quoteReplacement(replacement);
        matcher.appendReplacement(sb, replacement);
    }
    matcher.appendTail(sb);

    if (!found) {
        // No substitution needed
        return value;
    }

    // If the substitution resulted in new patterns, recurse
    String newValue = sb.toString();
    if (newValue.contains("${")) {
        // Prevent infinite recursion by limiting depth
        return findAndSubst(key, props); // simple recursion, could add depth limit
    }
    return newValue;
}

