    // Perform replacement iteratively until no more ${...} patterns remain.
    boolean found = false;
    while (matcher.find()) {
        found = true;
        String varName = matcher.group(1);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = ""; // Default to empty string if not found
        }
        // Escape backslashes and dollar signs in the replacement string for appendReplacement
        replacement = Matcher.quoteReplacement(replacement);
        matcher.appendReplacement(sb, replacement);
    }
    matcher.appendTail(sb);

    if (!found) {
        // No substitution needed
        return value;
    }

    // If the substitution resulted in new patterns, recurse
    String newValue = sb.toString();
    if (newValue.contains("${")) {
